<?php

use Illuminate\Support\Facades\Route;
use App\Http\Controllers\PageController;
use App\Http\Controllers\ReservationController;
use App\Http\Controllers\AdminController;
use App\Http\Controllers\ReviewController;
use App\Http\Controllers\AdminAuthController;


// Auth routes (generated by laravel/ui)
Auth::routes();

// Public pages
Route::get('/', [PageController::class, 'home']);
Route::get('/home', [PageController::class, 'home']);
Route::get('/venues', [PageController::class, 'venues']);

// Availability API (public — used by calendar)
Route::get('/api/availability', [ReservationController::class, 'availability']);

// Public reservation form (no login required)
Route::get('/reservation/new', [ReservationController::class, 'add_form']);

// Authenticated user routes
Route::middleware('auth')->group(function () {
    Route::get('/reservation/list',           [ReservationController::class, 'list']);
    Route::post('/reservation/new',           [ReservationController::class, 'save_reservation']);
    Route::get('/reservation/update/{id}',    [ReservationController::class, 'update_form']);
    Route::post('/reservation/update/{id}',   [ReservationController::class, 'updated_reservation']);
    Route::get('/reservation/delete/{id}',    [ReservationController::class, 'delete_reservation']);
    Route::patch('/reservation/{id}/cancel',    [ReservationController::class, 'cancel_reservation']);

    // Reviews — regular users only (admin guard inside controller)
    Route::get('/reservation/{id}/review',    [ReviewController::class, 'create']);
    Route::post('/reservation/{id}/review',   [ReviewController::class, 'store']);
});

// Admin routes
Route::middleware(['auth', 'admin'])->prefix('admin')->group(function () {
    Route::get('/dashboard',                  [AdminController::class, 'dashboard']);
    Route::get('/blocked-dates',              [AdminController::class, 'blocked_dates']);
    Route::post('/blocked-dates',             [AdminController::class, 'block_date']);
    Route::get('/blocked-dates/delete/{id}',  [AdminController::class, 'unblock_date']);

    Route::get('/reports',                    [AdminController::class, 'reports']);
}); 

Route::post('/admin/verify-code', [AdminAuthController::class, 'verifyCode'])
    ->name('admin.verify.code');

Route::get('/admin/register', [AdminAuthController::class, 'showRegister'])
    ->name('admin.register');

Route::post('/admin/register', [AdminAuthController::class, 'register'])
    ->name('admin.register.submit');